    const uploadCode = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "uploadCode" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("uploadCode"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "uploadCode" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("uploadCode")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "uploadCode" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("uploadCode"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "uploadCode" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("uploadCode")))));
    const updateComplete = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "updateComplete" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("updateComplete"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "updateComplete" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("updateComplete")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "updateComplete" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("updateComplete"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "updateComplete" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("updateComplete")))));
    const insertComplete = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "insertComplete" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("insertComplete"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "insertComplete" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("insertComplete")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "insertComplete" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("insertComplete"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "insertComplete" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("insertComplete")))));
    if (uploadCode !== '' || insertComplete !== '') {
        if (uploadCode === '0') {
            await $c.win.alert('저장되었습니다.');
        } else {
            if (uploadCode === '1') {
                await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
            } else {
                if (uploadCode === '2') {
                    await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                } else {
                    await $c.win.alert('저장시 오류가 발생하였습니다.');
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
