 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/listInvstg/pubOfrSchdl.do",
        ref: "dma_registerReq",
        target: "dlt_attachFileList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
